    const project = createTempProject();
    try {
      writeConfig(project.root, {
        schema: 'spec-driven',
        tests: [{ root: 'src', framework: 'vite-plus', includes: ['**/*.{ts,tsx}'] }],
      });
      const longPath = `src/${'x'.repeat(1001)}.ts`;
