    } finally {
      dir.cleanup();
    }
  });

  it('两 suite 不同阈值时汇总按 suite 分组（overrides 字段语义为 suite 分组）', () => {
    const dir = createTempDir();
    try {
      // 源码树分组需显式 includes；省略 includes 时仅 default_glob（测试文件）入 scope
      writeTestsConfig(dir.root, [
        {
          root: 'pkg-a',
          framework: 'vitest',
          includes: ['**/*.{ts,tsx}'],
          coverage: { lines: 90, branches: 90, functions: 90 },
          mutation: { score: 90 },
        },
        {
          root: 'pkg-b',
          framework: 'vite-plus',
          includes: ['**/*.{ts,tsx}'],
          coverage: { lines: 60, branches: 60, functions: 60 },
          mutation: { score: 50 },
        },
      ]);
      const sub1 = createSubReport({
        framework: 'vitest',
        directory: 'pkg-a',
        source_files: [
          sfe('pkg-a/a.ts', {
            total_lines: 10,
            covered_lines: 10,
            lines: 100,
            branches: 100,
            functions: 100,
            total_branches: 10,
            covered_branches: 10,
            total_functions: 10,
            covered_functions: 10,
          }),
        ],
        coverage: {
          pass: true,
          measured: { lines: 100, branches: 100, functions: 100 },
          thresholds: { lines: 90, branches: 90, functions: 90 },
        },
        mutation: {
          pass: true,
          score: 95,
          threshold: 90,
          measured: {
            killed: 9,
            survived: 1,
            timeout: 0,
            noCoverage: 0,
            compileError: 0,
            runtimeError: 0,
            ignored: 0,
            total: 10,
            detected: 9,
            undetected: 1,
          },
        },
      });
      const sub2 = createSubReport({
        framework: 'vite-plus',
        directory: 'pkg-b',
        source_files: [
          sfe('pkg-b/b.ts', {
            total_lines: 10,
            covered_lines: 10,
            lines: 100,
            branches: 100,
            functions: 100,
            total_branches: 10,
            covered_branches: 10,
            total_functions: 10,
            covered_functions: 10,
          }),
        ],
        coverage: {
          pass: true,
          measured: { lines: 100, branches: 100, functions: 100 },
          thresholds: { lines: 60, branches: 60, functions: 60 },
        },
        mutation: {
          pass: true,
          score: 80,
          threshold: 50,
          measured: {
            killed: 8,
            survived: 2,
            timeout: 0,
            noCoverage: 0,
            compileError: 0,
            runtimeError: 0,
            ignored: 0,
            total: 10,
            detected: 8,
            undetected: 2,
          },
        },
      });
      const summary = generateSummaryReport(
        [sub1, sub2],
        dir.root,
        path.join(dir.root, 'reports', 'test'),
      );
      expect(summary.coverage?.overrides?.length).toBeGreaterThanOrEqual(2);
      expect(summary.mutation?.overrides?.some((o) => o.glob === 'pkg-a')).toBe(true);
      expect(summary.mutation?.overrides?.some((o) => o.glob === 'pkg-b')).toBe(true);
    } finally {
      dir.cleanup();
    }
  });

  it('配置无顶层全局 test.coverage/test.mutation 块时报告仍能给出阈值结论', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [
        { root: 'src', framework: 'vitest', coverage: { lines: 50, branches: 50, functions: 50 } },
      ]);
      const sub = createSubReport({
        framework: 'vitest',
        directory: 'src',
        source_files: [sfe('src/foo.ts')],
        coverage: {
          pass: true,
          measured: { lines: 60, branches: 60, functions: 60 },
          thresholds: { lines: 50, branches: 50, functions: 50 },
        },
      });
      const summary = generateSummaryReport(
        [sub],
        dir.root,
        path.join(dir.root, 'reports', 'test'),
      );
      expect(summary.coverage).not.toBeNull();
      expect(summary.coverage!.thresholds.lines).toBe(50);
    } finally {
      dir.cleanup();
    }
  });

  it('coverage 产物缺失或 JSON 非法时子报告错误字段明确、不崩溃', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [{ root: 'src', framework: 'vitest' }]);
      const result = makeExecutionResult({
        coverage: null,
        error: 'coverage missing',
        sourceFiles: ['src/foo.ts'],
      });
      expect(() =>
        generateSubReport(
          'vitest',
          result,
          dir.root,
          path.join(dir.root, 'reports', 'test'),
          'src',
        ),
      ).not.toThrow();
    } finally {
      dir.cleanup();
    }
  });

  it('suite coverage.lines 为 -1 / 超过 100 时配置侧已拒绝，报告层使用 schema 默认', () => {
    const dir = createTempDir();
    try {
      fs.mkdirSync(path.join(dir.root, 'openspec'), { recursive: true });
      fs.writeFileSync(
        path.join(dir.root, 'openspec', 'config.json'),
        JSON.stringify({
          schema: 'spec-driven',
          tests: [{ root: 'src', framework: 'vitest', coverage: { lines: -1 } }],
        }),
        'utf-8',
      );
      const result = makeExecutionResult({
        coverage: { lines: 90, branches: 90, functions: 90, fileCoverage: null },
        sourceFiles: ['src/foo.ts'],
      });
      const sub = generateSubReport(
        'vitest',
        result,
        dir.root,
        path.join(dir.root, 'reports', 'test'),
        'src',
      );
      // invalid config → readConfig falls back → schema defaults
      expect(sub.coverage?.thresholds.lines).toBe(80);
    } finally {
      dir.cleanup();
    }
  });

  it('coverage.lines/branches/functions 均为 0 时阈值结论按 0 判定', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [
        {
          root: 'src',
          framework: 'vitest',
          coverage: { lines: 0, branches: 0, functions: 0 },
        },
      ]);
      const result = makeExecutionResult({
        coverage: { lines: 0, branches: 0, functions: 0, fileCoverage: null },
        sourceFiles: ['src/foo.ts'],
      });
      const sub = generateSubReport(
        'vitest',
        result,
        dir.root,
        path.join(dir.root, 'reports', 'test'),
        'src',
      );
      expect(sub.coverage?.thresholds).toEqual({ lines: 0, branches: 0, functions: 0 });
      expect(sub.coverage?.pass).toBe(true);
    } finally {
      dir.cleanup();
    }
  });

  it('coverage.lines 为 100（上界）时使用 100', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [
        {
          root: 'src',
          framework: 'vitest',
          coverage: { lines: 100, branches: 100, functions: 100 },
        },
      ]);
      const result = makeExecutionResult({
        coverage: { lines: 100, branches: 100, functions: 100, fileCoverage: null },
        sourceFiles: ['src/foo.ts'],
      });
      const sub = generateSubReport(
        'vitest',
        result,
        dir.root,
        path.join(dir.root, 'reports', 'test'),
        'src',
      );
      expect(sub.coverage?.thresholds.lines).toBe(100);
    } finally {
      dir.cleanup();
    }
  });

  it('mutation.score 为 0 / 100 时汇总分组使用该值', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [
        {
          root: 'src',
          framework: 'vitest',
          includes: ['**/*.{ts,tsx}'],
          mutation: { score: 0 },
        },
      ]);
      const sub = createSubReport({
        framework: 'vitest',
        directory: 'src',
        source_files: [sfe('src/foo.ts')],
        mutation: {
          pass: true,
          score: 50,
          threshold: 0,
          measured: {
            killed: 1,
            survived: 1,
            timeout: 0,
            noCoverage: 0,
            compileError: 0,
            runtimeError: 0,
            ignored: 0,
            total: 2,
            detected: 1,
            undetected: 1,
          },
        },
      });
      const summary = generateSummaryReport(
        [sub],
        dir.root,
        path.join(dir.root, 'reports', 'test'),
      );
      const group = summary.mutation?.overrides?.find((o) => o.glob === 'src');
      expect(group?.threshold).toBe(0);
    } finally {
      dir.cleanup();
    }
  });

  it('tests: [] 时阈值回退行为明确（不读旧全局块）', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, []);
      const result = makeExecutionResult({
        coverage: { lines: 90, branches: 90, functions: 90, fileCoverage: null },
      });
      const sub = generateSubReport(
        'vitest',
        result,
        dir.root,
        path.join(dir.root, 'reports', 'test'),
        '.',
      );
      expect(sub.coverage?.thresholds).toEqual({ lines: 80, branches: 70, functions: 75 });
    } finally {
      dir.cleanup();
    }
  });

  it('subReports: []（空数组）时汇总报告结构合法', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [{ root: 'src', framework: 'vitest' }]);
      const summary = generateSummaryReport([], dir.root, path.join(dir.root, 'reports', 'test'));
      expect(summary.total).toBe(0);
      expect(summary.conclusion).toBeDefined();
    } finally {
      dir.cleanup();
    }
  });

  it('subReports 为单元素时分组仅一条', () => {
    const dir = createTempDir();
    try {
      writeTestsConfig(dir.root, [
        {
          root: 'src',
          framework: 'vitest',
          includes: ['**/*.{ts,tsx}'],
          mutation: { score: 70 },
        },
      ]);
      const sub = createSubReport({
        framework: 'vitest',
        directory: 'src',
        source_files: [sfe('src/foo.ts')],
        mutation: {
          pass: true,
          score: 80,
          threshold: 70,
          measured: {
            killed: 8,
            survived: 2,
            timeout: 0,
            noCoverage: 0,
            compileError: 0,
            runtimeError: 0,
            ignored: 0,
            total: 10,
            detected: 8,
            undetected: 2,
          },
        },
      });
      const summary = generateSummaryReport(
        [sub],
        dir.root,
        path.join(dir.root, 'reports', 'test'),
      );
      expect(summary.mutation?.overrides?.length).toBe(1);
    } finally {
      dir.cleanup();
    }
  });
});

// ===========================================================================
// derivePlanId — 目录 id（AC-2）
// ===========================================================================

describe('derivePlanId', () => {
  it("directory='.' + framework='vitest' → 'vitest'（无前导 _、无 .json）", () => {
    expect(derivePlanId('.', 'vitest')).toBe('vitest');
    expect(derivePlanId('.', 'vitest')).not.toContain('.json');
    expect(derivePlanId('.', 'vitest')).not.toMatch(/^_/);
  });

  it("directory='plugins/dev-team/bin' + framework='vite-plus' → 'plugins_dev-team_bin_vite-plus'", () => {
    expect(derivePlanId('plugins/dev-team/bin', 'vite-plus')).toBe(
      'plugins_dev-team_bin_vite-plus',
    );
  });

  it('framework 为空字符串时仍参与拼接且不抛异常', () => {
    expect(() => derivePlanId('.', '')).not.toThrow();
    expect(derivePlanId('.', '')).toBe('');
    expect(derivePlanId('plugins/dev-team', '')).toBe('plugins_dev-team_');
  });

  it("directory='' 与 directory='.' 行为一致（均为无前缀 framework）", () => {
    expect(derivePlanId('', 'vitest')).toBe(derivePlanId('.', 'vitest'));
  });

  it('Windows 反斜杠路径消毒为下划线', () => {
    expect(derivePlanId('plugins\\dev-team\\bin', 'vitest')).toBe('plugins_dev-team_bin_vitest');
  });

  it('尾部斜杠经路径分隔符替换后仍返回无 .json 的字符串', () => {
    const id = derivePlanId('plugins/dev-team/', 'vitest');
    expect(id).not.toContain('.json');
    expect(id).toContain('vitest');
    expect(id).toContain('plugins');
  });

  it('超长 directory（>1000 chars）仍返回无 .json 的字符串', () => {
    const longDir = `a/${'b'.repeat(1001)}/c`;
    const id = derivePlanId(longDir, 'jest');
    expect(id.endsWith('_jest')).toBe(true);
    expect(id).not.toContain('.json');
    expect(id.length).toBeGreaterThan(1000);
  });
});

