// ===========================================================================

describe('config-driven 过滤 — 非空 modules 经 test_detect_frameworks 过滤后推导', () => {
  it('modules: ["src/commands/test-resolve-paths.ts", "node_modules/some-dep/index.ts"] 时仅前者进入 unit_tests (AC-3)', () => {
    const project = createTempProject({
      schema: 'spec-driven',
